from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json
base = 'https://www.walmartcanada.ca/suppliers'
root = Path('products/services/canadian-public-catalogue-qa-pilot')
raw = (root / 'raw/walmart-canada-supplier-route.html').read_bytes()
class Links(HTMLParser):
    def __init__(self):
        super().__init__()
        self.current = None
        self.results = []
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.current = (dict(attrs).get('href', ''), [])
    def handle_data(self, data):
        if self.current is not None:
            self.current[1].append(data)
    def handle_endtag(self, tag):
        if tag != 'a' or self.current is None:
            return
        href, parts = self.current
        self.current = None
        label = ' '.join(' '.join(parts).split())
        url = urljoin(base, href)
        if href and urlsplit(url).scheme in ('https', 'http') and any(term in (label + ' ' + url).lower() for term in ('suppl', 'vendor', 'procure', 'contact', 'service', 'goods', 'application')):
            entry = {'label': label, 'url': url}
            if entry not in self.results:
                self.results.append(entry)
parser = Links()
parser.feed(raw.decode('utf-8', errors='replace'))
result = {'source': base, 'source_sha256': hashlib.sha256(raw).hexdigest(), 'route_pointer_count': len(parser.results), 'route_pointers': parser.results[:40], 'scope': 'Anchor labels and destinations on one captured page. Pointers alone do not establish eligibility or an invitation to propose services.'}
(root / 'walmart-route-pointers.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({k: v for k, v in result.items() if k != 'route_pointers'}, ensure_ascii=False))
